import{_ as t}from"./plugin-vue_export-helper-c27b6911.js";import{o as d,c as r,e}from"./app-db7b9325.js";const n={},a=e('<h1 id="金蝶插件类型" tabindex="-1"><a class="header-anchor" href="#金蝶插件类型" aria-hidden="true">#</a> 金蝶插件类型</h1><p>金蝶云·星空（BOS 平台）目前（2025 年）所有官方提供的、真正常用的插件基类就只有下面这 <strong>10 个</strong>，基本上覆盖了 100% 的开发场景。<br> 我按使用频率从高到低给你排好序，并标明到底注册到哪里：</p><table><thead><tr><th>序号</th><th>基类名称</th><th>主要用途</th><th>注册位置（开发工具）</th><th>使用频率</th></tr></thead><tbody><tr><td>1</td><td><strong>AbstractBillPlugIn</strong></td><td>单据界面所有自定义按钮、事件（打开单据后看到的界面）</td><td>单据界面插件（或设计器按钮直接填插件类）</td><td>★★★★★</td></tr><tr><td>2</td><td><strong>AbstractListPlugIn</strong></td><td>列表界面所有自定义按钮、事件（列表工具栏按钮）</td><td>列表界面插件</td><td>★★★★★</td></tr><tr><td>3</td><td><strong>AbstractOperationServicePlugIn</strong></td><td>列表批量操作按钮（支持多选，显示绿勾红叉结果）</td><td>操作服务插件</td><td>★★★★</td></tr><tr><td>4</td><td><strong>AbstractBillServicePlugIn</strong></td><td>单据的保存、审核、反审核、删除等操作的前后事件</td><td>单据服务插件（替代旧的 Save/AuditPlugIn）</td><td>★★★★</td></tr><tr><td>5</td><td><strong>AbstractDynamicFormPlugIn</strong></td><td>自定义表单（动态表单设计器做的页面）所有按钮事件</td><td>动态表单插件</td><td>★★★</td></tr><tr><td>6</td><td><strong>AbstractReportPlugIn</strong></td><td>帐表、报表自定义按钮和行颜色、单元格样式等</td><td>报表插件</td><td>★★★</td></tr><tr><td>7</td><td><strong>AbstractScheduleServicePlugIn</strong></td><td>定时任务（每天/每周自动执行的后台任务）</td><td>定时任务插件</td><td>★★</td></tr><tr><td>8</td><td><strong>AbstractWebApiPlugIn</strong></td><td>自定义 Web API 接口（给外部系统调用）</td><td>WebApi 插件</td><td>★★</td></tr><tr><td>9</td><td><strong>AbstractImportServicePlugIn</strong></td><td>自定义导入插件（Excel 导入时加自己的校验逻辑）</td><td>导入服务插件</td><td>★★</td></tr><tr><td>10</td><td><strong>AbstractAppPlugIn</strong></td><td>移动端 APP 自定义页面插件（极少用）</td><td>移动应用插件</td><td>★</td></tr></tbody></table><h3 id="已经彻底淘汰或几乎没人用的老基类-不要再用" tabindex="-1"><a class="header-anchor" href="#已经彻底淘汰或几乎没人用的老基类-不要再用" aria-hidden="true">#</a> 已经彻底淘汰或几乎没人用的老基类（不要再用）</h3><table><thead><tr><th>基类名称</th><th>说明</th><th>替代方案</th></tr></thead><tbody><tr><td>AbstractSavePlugIn</td><td>老版保存插件</td><td>→ AbstractBillServicePlugIn</td></tr><tr><td>AbstractAuditPlugIn</td><td>老版审核插件</td><td>→ AbstractBillServicePlugIn</td></tr><tr><td>AbstractUnAuditPlugIn</td><td>老版反审核插件</td><td>→ AbstractBillServicePlugIn</td></tr><tr><td>AbstractPushPlugIn</td><td>老版下推插件</td><td>→ AbstractOperationServicePlugIn</td></tr><tr><td>AbstractConvertPlugIn</td><td>老版转换插件</td><td>→ AbstractOperationServicePlugIn</td></tr></tbody></table><h3 id="_99-开发者每天只用前-4-个就够了" tabindex="-1"><a class="header-anchor" href="#_99-开发者每天只用前-4-个就够了" aria-hidden="true">#</a> 99% 开发者每天只用前 4 个就够了</h3><table><thead><tr><th>你要做什么？</th><th>用哪个基类？</th><th>注册到哪里？</th></tr></thead><tbody><tr><td>单据上加一个按钮（比如“打印”“生成XX”）</td><td>AbstractBillPlugIn</td><td>单据界面插件</td></tr><tr><td>列表上加一个普通按钮</td><td>AbstractListPlugIn</td><td>列表界面插件</td></tr><tr><td>列表上加一个“批量”按钮（多选后执行）</td><td>AbstractOperationServicePlugIn</td><td>操作服务插件</td></tr><tr><td>单据保存/审核前校验、后写其他单据</td><td>AbstractBillServicePlugIn</td><td>单据服务插件</td></tr></tbody></table><p>记住这 4 个基类 + 注册位置，你在金蝶里 95% 的插件需求都可以完美解决。其余 6 个属于“偶尔需要”或“专业场景”。</p><p>总结一句话：<br><strong>日常开发只认这四个就够了：BillPlugIn → ListPlugIn → OperationServicePlugIn → BillServicePlugIn</strong><br> 其他的全是“高级玩家”用的。</p>',9),s=[a];function l(c,o){return d(),r("div",null,s)}const h=t(n,[["render",l],["__file","金蝶插件类型.html.vue"]]);export{h as default};
